// `andesim doctor` -- read-only environment health.
//
// The four carried-over sections (artifacts, submodules, toolchain, runtime)
// plus the Summary line are a faithful C++ port of the Python hsim `cmd_doctor`,
// kept byte-identical so the parity flywheel stays green. The detail strings
// point at scripts/build_all.sh -- the build entry point, since the build
// command moved out of the binary into that script (hsim's doctor matches).
// After Summary the driver appends an `engines:` readout sourced from F2
// discovery -- new surface, INFO-tagged, never affecting the exit code (which
// stays 1 iff any FAIL row, exactly as the golden).
#include <algorithm>
#include <cctype>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include <sys/statvfs.h>
#include <unistd.h>

#include "cli.hpp"
#include "engine_registry.hpp"
#include "repo_root.hpp"
#include "shm.hpp"
#include "strutil.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// One diagnostic row. status is PASS | FAIL | WARN | INFO; only PASS/FAIL/WARN
// feed the summary, and only FAIL gates the exit code.
struct Row {
  std::string name;
  std::string status;
  std::string detail;
};

// Strip every leading and trailing `c` from `s` (mirrors Python str.strip(c)).
std::string strip_char(std::string s, char c) {
  size_t b = 0, e = s.size();
  while (b < e && s[b] == c) ++b;
  while (e > b && s[e - 1] == c) --e;
  return s.substr(b, e - b);
}

// --- artifacts --------------------------------------------------------------

std::vector<Row> doctor_artifacts() {
  const fs::path root = repo_root();
  struct A {
    const char* label;
    const char* env;
    fs::path def;
  };
  // The vsim/qemu defaults come straight from the registry's resolvers
  // (vsim_scan_dir / builtin_qemu_arch), so doctor reports the same paths the
  // engine would use instead of re-deriving the env -> QEMU_BIN_DIR -> legacy
  // tiers. Env overrides still match hsim's _ARTIFACT_ENV; order (vsim, qemu,
  // plugin) mirrors the golden's dict order.
  const A arts[] = {
      {"vsim", "VSIM_BIN", vsim_scan_dir() / "sim_ax45mpv_premium"},
      {"qemu64", "VSIM_QEMU", builtin_qemu_arch(64).bin_path},
      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
  };
  std::vector<Row> rows;
  for (const A& a : arts) {
    const char* ov = std::getenv(a.env);
    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
    if (fs::is_regular_file(p))
      rows.push_back({a.label, "PASS", p.string()});
    else
      rows.push_back(
          {a.label, "FAIL", "missing " + p.string() + " -- run scripts/build_all.sh"});
  }

  const fs::path fix = root / "tests" / "fixtures";
  size_t elfs = 0;
  std::error_code ec;
  if (fs::is_directory(fix, ec))
    for (const auto& e : fs::directory_iterator(fix, ec))
      if (e.path().extension() == ".elf") ++elfs;
  if (elfs > 0)
    rows.push_back(
        {"fixtures", "PASS", std::to_string(elfs) + " ELFs in " + fix.string()});
  else
    rows.push_back({"fixtures", "FAIL",
                    "no *.elf in " + fix.string() +
                        " -- run make -C tests/fixtures"});
  return rows;
}

// --- submodules -------------------------------------------------------------

std::vector<Row> doctor_submodules() {
  const fs::path root = repo_root();
  struct M {
    const char* name;
    fs::path marker;
    const char* rel;  // marker, repo-relative (the PASS detail)
  };
  // QEMU and vsim are no longer submodules -- both are integrated as prebuilt
  // external binaries, checked in the artifacts section (qemu/vsim rows) via
  // VSIM_QEMU / VSIM_BIN_DIR. The one remaining submodule is the shared ABI.
  const M ms[] = {
      {"include/ (abi)", root / "include" / "hybrid" / "state_abi.h",
       "include/hybrid/state_abi.h"},
  };
  std::vector<Row> rows;
  for (const M& m : ms) {
    if (fs::is_regular_file(m.marker))
      rows.push_back({m.name, "PASS", m.rel});
    else
      rows.push_back({m.name, "FAIL",
                      "missing " + m.marker.string() +
                          " -- run 'git submodule update --init --recursive'"});
  }
  return rows;
}

// --- toolchain --------------------------------------------------------------

// First PATH directory holding an executable non-directory named `tool`, joined
// the way shutil.which reports it (dir + '/' + tool). "" if not found.
std::string which(const std::string& tool) {
  const char* path = std::getenv("PATH");
  if (!path) return "";
  const std::string p(path);
  for (size_t i = 0; i <= p.size();) {
    size_t j = p.find(':', i);
    if (j == std::string::npos) j = p.size();
    std::string dir = p.substr(i, j - i);
    i = j + 1;
    if (dir.empty()) continue;
    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
    std::error_code ec;
    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
      return cand;
  }
  return "";
}

// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
// to the value with surrounding whitespace, then double, then single quotes
// stripped (mirrors hsim._read_hybrid_toolchain).
bool parse_toolchain_line(const std::string& line, std::string& out) {
  size_t i = 0, n = line.size();
  auto skip_ws = [&] {
    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
  };
  skip_ws();
  const std::string kw = "export";
  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
    i += kw.size();
    skip_ws();
  }
  const std::string key = "HYBRID_TOOLCHAIN";
  if (line.compare(i, key.size(), key) != 0) return false;
  i += key.size();
  skip_ws();
  if (i >= n || line[i] != '=') return false;
  std::string rest = line.substr(i + 1);  // everything after '='
  if (rest.empty()) return false;         // regex (.+?) needs >= 1 char
  size_t b = 0, e = rest.size();
  while (b < e && std::isspace(static_cast<unsigned char>(rest[b]))) ++b;
  while (e > b && std::isspace(static_cast<unsigned char>(rest[e - 1]))) --e;
  std::string val = strip_char(rest.substr(b, e - b), '"');
  out = strip_char(val, '\'');
  return true;
}

// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
// assignment in config.env. "" if neither yields a value.
std::string read_hybrid_toolchain() {
  const char* env = std::getenv("HYBRID_TOOLCHAIN");
  if (env && *env) return env;
  std::ifstream f(repo_root() / "config.env");
  if (!f) return "";
  std::string line, val;
  while (std::getline(f, line))
    if (parse_toolchain_line(line, val)) return val;
  return "";
}

std::vector<Row> doctor_toolchain() {
  struct T {
    const char* tool;
    const char* hint;
    bool warn_only;  // a missing podman warns; ninja/make fail
  };
  const T tools[] = {
      {"ninja", "needed by scripts/build_all.sh of QEMU", false},
      {"make", "needed by scripts/build_all.sh of fixtures", false},
      {"podman", "needed by scripts/build_all.sh of vsim (or docker shim)", true},
  };
  std::vector<Row> rows;
  for (const T& t : tools) {
    std::string found = which(t.tool);
    if (!found.empty())
      rows.push_back({t.tool, "PASS", found});
    else
      rows.push_back({t.tool, t.warn_only ? "WARN" : "FAIL",
                      std::string("not on PATH -- ") + t.hint});
  }

  std::string tc = read_hybrid_toolchain();
  if (tc.empty()) {
    rows.push_back({"HYBRID_TOOLCHAIN", "WARN",
                    "not set -- needed for fixture build (see config.env)"});
  } else {
    fs::path gcc = fs::path(tc) / "bin" / "riscv64-unknown-elf-gcc";
    if (fs::is_regular_file(gcc))
      rows.push_back({"riscv64-unknown-elf-gcc", "PASS", gcc.string()});
    else
      rows.push_back({"riscv64-unknown-elf-gcc", "FAIL",
                      "missing " + gcc.string() +
                          " -- check HYBRID_TOOLCHAIN=" + tc});
  }
  return rows;
}

// --- runtime ----------------------------------------------------------------

constexpr long kDefaultJobs = 8;

std::vector<Row> doctor_runtime() {
  std::vector<Row> rows;
  long nproc = sysconf(_SC_NPROCESSORS_ONLN);
  if (nproc < 1) nproc = 1;
  rows.push_back({"nproc", "INFO", std::to_string(nproc)});

  std::error_code ec;
  if (fs::is_directory("/dev/shm", ec)) {
    struct statvfs vfs{};
    unsigned long long free_gb = 0;
    if (statvfs("/dev/shm", &vfs) == 0)
      free_gb = static_cast<unsigned long long>(vfs.f_bavail) * vfs.f_frsize /
                (1024ULL * 1024 * 1024);
    rows.push_back({"/dev/shm free", free_gb >= 4 ? "PASS" : "WARN",
                    std::to_string(free_gb) + " GB"});
  } else {
    rows.push_back({"/dev/shm", "WARN",
                    "not present -- e2e fixtures will fall back to $TMPDIR"});
  }

  long suggested = std::min(nproc, kDefaultJobs);
  rows.push_back({"JOBS suggestion", "INFO",
                  std::to_string(suggested) + " (default cap = " +
                      std::to_string(kDefaultJobs) + ")"});
  return rows;
}

// --- engines (C++-only readout, after Summary) ------------------------------

// Reflects `list engines` from the same F2 discovery, in doctor's row idiom.
// INFO-tagged and printed after Summary, so it never moves the summary counts
// or the exit code. Discovery warnings surface as WARN rows here.
void print_engines_section() {
  Discovery disc = discover_engines();
  size_t w = 0;
  for (const EngineDescriptor& e : disc.engines) w = std::max(w, e.id.size());

  std::printf("\nengines:\n");
  for (const EngineDescriptor& e : disc.engines)
    std::printf("  [INFO] %s  kind=%s vlen=%s triggers=%s\n",
                ljust(e.id, w).c_str(), e.kind.c_str(), vlen_str(e.vlen).c_str(),
                join(e.triggers).c_str());
  for (const std::string& warn : disc.warnings)
    std::printf("  [WARN] %s\n", warn.c_str());
}

// The shared-mmap backing tiers (F1 resolver order) with their free space,
// plus WSL2 advice. INFO/WARN-tagged and printed after Summary like engines,
// so the carried-over report keeps byte-parity with the Python golden.
void print_mmap_section() {
  const std::vector<MmapTier> tiers = mmap_tiers();
  size_t w = 0;
  for (const MmapTier& t : tiers) w = std::max(w, t.label.size());

  std::printf("\nmmap tiers:\n");
  int n = 0;
  for (const MmapTier& t : tiers) {
    struct statvfs vfs{};
    std::string free = "missing";
    if (statvfs(t.dir.c_str(), &vfs) == 0) {
      const double gib = static_cast<double>(vfs.f_bavail) * vfs.f_frsize /
                         (1024.0 * 1024 * 1024);
      char buf[32];
      std::snprintf(buf, sizeof(buf), "free: %.1f GiB", gib);
      free = buf;
    }
    std::printf("  [INFO] tier %d  %s  %s\n", ++n, ljust(t.label, w).c_str(),
                free.c_str());
  }

  std::string proc_version;
  if (std::FILE* f = std::fopen("/proc/version", "r")) {
    char buf[512] = {};
    const size_t got = std::fread(buf, 1, sizeof(buf) - 1, f);
    proc_version.assign(buf, got);
    std::fclose(f);
  }
  std::error_code ec;
  for (const std::string& warn :
       wsl_warnings(proc_version, fs::current_path(ec).string(), tiers))
    std::printf("  [WARN] %s\n", warn.c_str());
}

struct Section {
  const char* title;
  std::vector<Row> rows;
};

}  // namespace

int cmd_doctor(const Cli&) {
  std::vector<Section> sections = {
      {"artifacts", doctor_artifacts()},
      {"submodules", doctor_submodules()},
      {"toolchain", doctor_toolchain()},
      {"runtime", doctor_runtime()},
  };

  size_t name_width = 0;
  for (const Section& s : sections)
    for (const Row& r : s.rows) name_width = std::max(name_width, r.name.size());

  int passes = 0, fails = 0, warns = 0;
  for (const Section& s : sections) {
    std::printf("%s:\n", s.title);
    for (const Row& r : s.rows) {
      if (r.status == "PASS") ++passes;
      else if (r.status == "FAIL") ++fails;
      else if (r.status == "WARN") ++warns;
      std::printf("  [%-4s] %s  %s\n", r.status.c_str(),
                  ljust(r.name, name_width).c_str(), r.detail.c_str());
    }
    std::printf("\n");
  }
  std::printf("Summary: %d PASS, %d FAIL, %d WARN\n", passes, fails, warns);

  print_engines_section();
  print_mmap_section();
  return fails > 0 ? 1 : 0;
}

}  // namespace andes_sim

// Shared-mmap allocation for andesim.
//
// The caller asks for `size` bytes; we resolve a backing directory over a
// tier list (first fit wins, fit = size + 256 MiB free), allocate a sparse
// file with mkstemp+truncate, and print one status line that always names
// the chosen tier -- and, when we fell past /dev/shm, why. HSIM_MMAP_DIR
// pins a single tier (hard error if it does not fit; no fallback past it).
#ifndef ANDESIM_SHM_HPP
#define ANDESIM_SHM_HPP

#include <functional>
#include <string>
#include <vector>

namespace andes_sim {

// Free-space headroom a tier must have beyond the requested size.
inline constexpr long long kMmapSafetyMargin = 256LL * 1024 * 1024;

// One backing-store candidate: the directory plus the label used in
// status/error messages ("/dev/shm", "~/.cache/andesim", "HSIM_MMAP_DIR=..").
struct MmapTier {
  std::string dir;
  std::string label;
};

// resolve_mmap_dir result: the chosen dir ("" on failure) and, when a tier
// was skipped, a human note saying which and why ("" when tiers[0] fit).
struct MmapDirChoice {
  std::string dir;
  std::string note;
};

// Parse "8G" / "512M" / "1024" / "1.5G" into a positive byte count. On success
// returns the count and leaves `err` empty; on failure returns 0 and sets `err`
// to the argparse-style message. Mirrors hsim_shm.parse_size (fractional values
// truncate, like Python int(float(num) * mult)).
long long parse_size(const std::string& spec, std::string& err);

// L26/F2: the physical shared mmap is one V-scratch page (HYBRID_V_SCRATCH_BYTES)
// larger than the program's --mem-size, so the V-register transport page sits
// just ABOVE the program's declared RAM. No program layout -- low stack, top-of-
// RAM stack, or a heap grown to the ceiling -- can reach a page past its own
// RAM, so the scratch can never be clobbered. The vsim side parks the scratch
// at the mmap's top page (v_scratch_gpa), which equals ram_base + program_bytes.
long long physical_mmap_bytes(long long program_bytes);

// The largest --mem-size whose physical mmap still fits the 2 GiB AE350 DRAM
// window (program_bytes + scratch page <= 2 GiB). --mem-size is capped here.
long long max_program_mem_bytes();

// First-fit resolver over `tiers`. `probe(dir)` returns the dir's free bytes,
// or -1 when it does not exist. A tier fits when probe >= size + margin.
// On success `err` is empty; when nothing fits, returns {"", ""} and `err`
// names every tier's reason plus the HSIM_MMAP_DIR hint. Pure: no env, no
// filesystem -- testable with a fake probe.
MmapDirChoice resolve_mmap_dir(
    const std::vector<MmapTier>& tiers, long long size,
    const std::function<long long(const std::string&)>& probe,
    std::string& err);

// Build the real tier list from the environment:
//   HSIM_MMAP_DIR set -> that single pinned tier;
//   else            -> /dev/shm, then $XDG_CACHE_HOME|~/.cache + /andesim
//                      (created here so the free-space probe can see it).
std::vector<MmapTier> mmap_tiers();

// WSL2 advice for `doctor`: given /proc/version contents, the repo dir, and
// the mmap tier list, return warning lines. Empty when not on WSL2. On WSL2:
// always the .wslconfig memory= hint (tmpfs is capped by the WSL VM), plus a
// drvfs warning for the repo or any tier dir under /mnt/ (slow, and
// MAP_SHARED is not coherent across the 9p boundary). Pure -- testable.
std::vector<std::string> wsl_warnings(const std::string& proc_version,
                                      const std::string& repo_dir,
                                      const std::vector<MmapTier>& tiers);

// Convert a --mem-size spec into the fast leg's plain QEMU `-m` argv:
// {"-m", "<MiB>M"}. Empty spec -> {} with no error (QEMU as-is). Malformed
// specs and sizes that are not a whole MiB (QEMU's -m granularity) return {}
// and set `err`.
std::vector<std::string> qemu_m_args(const std::string& spec, std::string& err);

// Allocate a sparse mmap file of `size` bytes in the resolved dir (mkstemp +
// truncate), print one "[hsim mmap] <size> at <dir> (free: <free>)" line
// (plus "; fallback: <why>" when /dev/shm was skipped), and return its path.
// On failure returns "" and sets `err`. Caller owns the file (unlink when
// done).
std::string allocate(long long size, std::string& err,
                     const std::string& prefix = "hsim-shm.");

}  // namespace andes_sim

#endif  // ANDESIM_SHM_HPP

// Runtime engine discovery -- the hot-plug seam.
//
// discover_engines() returns the built-in qemu descriptor plus every engine
// found by scanning a directory and asking each binary to self-report via
// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
// into the framework; dropping a freshly built sim_<cfg> into the scan dir
// makes it appear here with no andesim rebuild.
//
// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
// $QEMU_BIN_DIR, falling back to the legacy in-tree <repo>/verilator/build.
#ifndef ANDESIM_ENGINE_REGISTRY_HPP
#define ANDESIM_ENGINE_REGISTRY_HPP

#include <filesystem>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "strutil.hpp"

namespace andes_sim {

// Built-in functional engine id. Declared once here so builtin_qemu and every
// lookup agree -- a renamed literal would otherwise break find_engine()
// lookups only at run time.
inline constexpr const char* kQemuId = "qemu";

struct Discovery {
  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
  std::vector<std::string> warnings;       // binaries that failed to describe
};

Discovery discover_engines();

// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
// QEMU_BIN_DIR) resolved env-first then from config.env, else the legacy in-tree
// <repo>/verilator/build.
std::filesystem::path vsim_scan_dir();

// The bundled qemu descriptor (no directory scan, no --describe subprocess).
// discover_engines() seeds the registry with it; `run --mode fast` resolves
// qemu through it directly, paying none of the Verilator-engine discovery cost.
EngineDescriptor builtin_qemu();

// Rewrite a discovered engine's identity from the third-party simulator name to
// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
// dedup or shown anywhere, so every downstream consumer (list / --engine /
// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
// other backend (qemu, a drop-in alioth/sid) passes through untouched.
inline void normalize_engine_label(EngineDescriptor& d) {
  if (d.type == "verilator") d.type = "vsim";
  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
  // report it under their internal name "csr" via --describe. Speak the CLI's
  // vocabulary in list too, like verilator -> vsim above.
  for (std::string& t : d.triggers)
    if (t == "csr") t = "marker";
}

}  // namespace andes_sim

#endif  // ANDESIM_ENGINE_REGISTRY_HPP

// Runtime engine discovery -- the hot-plug seam.
//
// discover_engines() returns the built-in qemu descriptor plus every engine
// found by scanning a directory and asking each binary to self-report via
// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
// into the framework; dropping a freshly built sim_<cfg> into the scan dir
// makes it appear here with no andesim rebuild.
//
// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
// $QEMU_BIN_DIR, falling back to the legacy in-tree <repo>/verilator/build.
#ifndef ANDESIM_ENGINE_REGISTRY_HPP
#define ANDESIM_ENGINE_REGISTRY_HPP

#include <filesystem>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "strutil.hpp"

namespace andes_sim {

// Built-in functional engine ids (the qemu64/qemu32 pair). Declared once here so
// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
// agree -- a renamed literal would otherwise break find_engine() lookups only at
// run time.
inline constexpr const char* kQemuId64 = "qemu64";
inline constexpr const char* kQemuId32 = "qemu32";

struct Discovery {
  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
  std::vector<std::string> warnings;       // binaries that failed to describe
};

Discovery discover_engines();

// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
// QEMU_BIN_DIR) resolved env-first then from config.env, else the legacy in-tree
// <repo>/verilator/build.
std::filesystem::path vsim_scan_dir();

// The bundled qemu descriptor (no directory scan, no --describe subprocess).
// discover_engines() seeds the registry with it; `run --mode fast` resolves
// qemu through it directly, paying none of the Verilator-engine discovery cost.
// builtin_qemu_arch(xlen) builds the rv64 "qemu64" (xlen=64) or rv32 "qemu32"
// (xlen=32, qemu-system-riscv32); builtin_qemu() is the rv64 default.
EngineDescriptor builtin_qemu_arch(int xlen);
EngineDescriptor builtin_qemu();

// Rewrite a discovered engine's identity from the third-party simulator name to
// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
// dedup or shown anywhere, so every downstream consumer (list / --engine /
// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
// other backend (qemu, a drop-in alioth/sid) passes through untouched.
inline void normalize_engine_label(EngineDescriptor& d) {
  if (d.type == "verilator") d.type = "vsim";
  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
  // report it under their internal name "csr" via --describe. Speak the CLI's
  // vocabulary in list / doctor too, like verilator -> vsim above.
  for (std::string& t : d.triggers)
    if (t == "csr") t = "marker";
}

// Select the cycle-accurate engine for `run --mode cycle` from an
// already-discovered set (pure; spawns nothing). With `want_id` empty, default
// to the sole cycle-accurate engine -- erroring if there are none or more than
// one (ambiguous). With `want_id` set, that engine must exist and be
// cycle-accurate. Returns nullptr and sets `err` (naming the available
// cycle-accurate ids) on any failure; the returned pointer aliases into
// `engines`, so it must outlive the result.
inline const EngineDescriptor* resolve_accurate_engine(
    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
    std::string& err) {
  auto is_accurate = [](const EngineDescriptor& e) {
    return e.kind == "cycle-accurate";
  };
  auto accurate_ids = [&] {
    std::vector<std::string> ids;
    for (const EngineDescriptor& e : engines)
      if (is_accurate(e)) ids.push_back(e.id);
    return join(ids, ", ");
  };

  if (!want_id.empty()) {  // explicit --engine
    for (const EngineDescriptor& e : engines) {
      if (e.id != want_id) continue;
      if (is_accurate(e)) return &e;
      err = "engine '" + want_id + "' is " +
            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
            "; a cycle-accurate engine is required";
      return nullptr;
    }
    std::string have = accurate_ids();
    err = "no engine '" + want_id + "'" +
          (have.empty() ? " (no cycle-accurate engines found)"
                        : " (cycle-accurate engines: " + have + ")");
    return nullptr;
  }

  // No --engine: default to the sole cycle-accurate engine.
  const EngineDescriptor* sole = nullptr;
  int n = 0;
  for (const EngineDescriptor& e : engines)
    if (is_accurate(e)) { sole = &e; ++n; }
  if (n == 1) return sole;
  if (n == 0)
    err = "model cycle: no cycle-accurate engine found "
          "(build one with: scripts/build_all.sh vsim)";
  else
    err = "model cycle: multiple cycle-accurate engines; select one with "
          "--engine (have: " + accurate_ids() + ")";
  return nullptr;
}

