// Shared-mmap allocation -- tiered backing-store resolver. See shm.hpp.
#include "shm.hpp"

#include <cctype>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <regex>
#include <vector>

#include <sys/stat.h>
#include <sys/statvfs.h>
#include <unistd.h>

#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F2)

namespace andes_sim {
namespace {

// Free bytes on the filesystem holding `dir`, or -1 if it does not exist.
long long free_bytes(const std::string& dir) {
  struct statvfs vfs;
  if (statvfs(dir.c_str(), &vfs) != 0) return -1;
  return static_cast<long long>(vfs.f_bavail) *
         static_cast<long long>(vfs.f_frsize);
}

// Human-readable byte count: "8.0 GiB", "512.0 MiB", "1024 B". Mirrors
// hsim_shm._format_bytes (one decimal, TiB/GiB/MiB/KiB, else "N B").
std::string format_bytes(long long n) {
  struct Unit {
    const char* suffix;
    long long mul;
  };
  static const Unit units[] = {
      {"TiB", 1024LL * 1024 * 1024 * 1024},
      {"GiB", 1024LL * 1024 * 1024},
      {"MiB", 1024LL * 1024},
      {"KiB", 1024LL},
  };
  for (const Unit& u : units) {
    if (n >= u.mul) {
      char buf[64];
      std::snprintf(buf, sizeof(buf), "%.1f %s",
                    static_cast<double>(n) / static_cast<double>(u.mul),
                    u.suffix);
      return buf;
    }
  }
  return std::to_string(n) + " B";
}

}  // namespace

long long parse_size(const std::string& spec, std::string& err) {
  static const std::regex re(R"(\s*(\d+(?:\.\d+)?)\s*([KMGT]?)\s*)",
                             std::regex::icase);
  std::smatch m;
  if (!std::regex_match(spec, m, re)) {
    err = "invalid mmap size '" + spec +
          "': expected <number>[K|M|G|T] (e.g. '128M', '8G', '1024')";
    return 0;
  }
  const double num = std::stod(m[1].str());
  long long mult = 1;
  if (m[2].length()) {
    switch (std::toupper(static_cast<unsigned char>(m[2].str()[0]))) {
      case 'K': mult = 1024LL; break;
      case 'M': mult = 1024LL * 1024; break;
      case 'G': mult = 1024LL * 1024 * 1024; break;
      case 'T': mult = 1024LL * 1024 * 1024 * 1024; break;
    }
  }
  // Truncate toward zero like Python int(float(num) * multiplier).
  const long long size =
      static_cast<long long>(num * static_cast<double>(mult));
  if (size <= 0) {
    err = "invalid mmap size '" + spec + "': must be > 0";
    return 0;
  }
  err.clear();
  return size;
}

// L26/F2: physical mmap = program RAM + one V-scratch page. See shm.hpp.
long long physical_mmap_bytes(long long program_bytes) {
  return program_bytes + HYBRID_V_SCRATCH_BYTES;
}

long long max_program_mem_bytes() {
  // AE350 DRAM window is 2 GiB; leave room for the scratch page on top.
  constexpr long long kAe350DramWindowBytes = 2LL * 1024 * 1024 * 1024;
  return kAe350DramWindowBytes - HYBRID_V_SCRATCH_BYTES;
}

std::vector<std::string> wsl_warnings(const std::string& proc_version,
                                      const std::string& repo_dir,
                                      const std::vector<MmapTier>& tiers) {
  std::string lower = proc_version;
  for (char& c : lower) c = static_cast<char>(std::tolower(
      static_cast<unsigned char>(c)));
  if (lower.find("microsoft") == std::string::npos) return {};

  std::vector<std::string> warns;
  warns.push_back(
      "WSL2: /dev/shm is capped by the WSL VM memory; raise memory= in "
      ".wslconfig if tier 1 is too small");
  if (repo_dir.starts_with("/mnt/"))
    warns.push_back("repo is under /mnt/ (drvfs): slow, and MAP_SHARED is "
                    "not coherent -- keep the repo in the Linux home (~)");
  for (const MmapTier& t : tiers)
    if (t.dir.starts_with("/mnt/"))
      warns.push_back("mmap dir " + t.dir +
                      " is under /mnt/ (drvfs): MAP_SHARED is not coherent "
                      "there -- use a Linux-side dir");
  return warns;
}

std::vector<std::string> qemu_m_args(const std::string& spec,
                                     std::string& err) {
  err.clear();
  if (spec.empty()) return {};
  const long long bytes = parse_size(spec, err);
  if (!err.empty()) {
    err = "--mem-size: " + err;
    return {};
  }
  if (bytes % (1024 * 1024) != 0) {
    err = "--mem-size '" + spec +
          "': QEMU's -m takes whole MiB; round to a multiple of 1M";
    return {};
  }
  return {"-m", std::to_string(bytes / (1024 * 1024)) + "M"};
}

MmapDirChoice resolve_mmap_dir(
    const std::vector<MmapTier>& tiers, long long size,
    const std::function<long long(const std::string&)>& probe,
    std::string& err) {
  const long long need = size + kMmapSafetyMargin;
  std::vector<std::string> reasons;
  for (const MmapTier& t : tiers) {
    const long long free = probe(t.dir);
    if (free >= need) {
      err.clear();
      std::string note;
      for (size_t i = 0; i < reasons.size(); i++)
        note += (i ? "; " : "") + reasons[i];
      return {t.dir, note};
    }
    reasons.push_back(free < 0 ? t.label + " missing"
                               : t.label + " too small (" +
                                     format_bytes(free) + " free)");
  }
  err = "no mmap directory can hold " + format_bytes(size) +
        " + 256 MiB margin: ";
  for (size_t i = 0; i < reasons.size(); i++)
    err += (i ? "; " : "") + reasons[i];
  err += "; set HSIM_MMAP_DIR to a directory with enough free space";
  return {"", ""};
}

std::vector<MmapTier> mmap_tiers() {
  if (const char* pinned = std::getenv("HSIM_MMAP_DIR"); pinned && pinned[0])
    return {{pinned, "HSIM_MMAP_DIR='" + std::string(pinned) + "'"}};

  std::string cache;
  if (const char* xdg = std::getenv("XDG_CACHE_HOME"); xdg && xdg[0])
    cache = std::string(xdg) + "/andesim";
  else if (const char* home = std::getenv("HOME"); home && home[0])
    cache = std::string(home) + "/.cache/andesim";

  std::vector<MmapTier> tiers = {{"/dev/shm", "/dev/shm"}};
  if (!cache.empty()) {
    std::error_code ec;
    std::filesystem::create_directories(cache, ec);  // probe needs it to exist
    tiers.push_back({cache, cache});
  }
  return tiers;
}

std::string allocate(long long size, std::string& err,
                     const std::string& prefix) {
  const MmapDirChoice choice =
      resolve_mmap_dir(mmap_tiers(), size, free_bytes, err);
  if (choice.dir.empty()) return "";

  std::string tmpl = choice.dir + "/" + prefix + "XXXXXX";
  std::vector<char> buf(tmpl.begin(), tmpl.end());
  buf.push_back('\0');
  const int fd = mkstemp(buf.data());
  if (fd < 0) {
    err = "failed to create mmap file in " + choice.dir;
    return "";
  }
  close(fd);
  const std::string path(buf.data());
  if (truncate(path.c_str(), size) != 0) {
    unlink(path.c_str());
    err = "failed to size mmap file " + path;
    return "";
  }

  std::string line = "[hsim mmap] " + format_bytes(size) + " at " +
                     choice.dir + " (free: " + format_bytes(free_bytes(choice.dir)) + ")";
  if (!choice.note.empty()) line += " (fallback: " + choice.note + ")";
  std::printf("%s\n", line.c_str());
  std::fflush(stdout);
  err.clear();
  return path;
}

}  // namespace andes_sim

// The bundled functional engine. QEMU does not implement --describe, so the
// descriptor is built in. The standalone (model=fast) run uses qemu's OWN
// default behavior as far as possible -- the user's post-`--` args (incl. an
// explicit -cpu) still win; only the hybrid fast-leg pins a -cpu. Binary path
// honors $VSIM_QEMU, then $QEMU_BIN_DIR (env or config.env), then the legacy
// in-tree build. Exposed (engine_registry.hpp) so `run --mode fast` resolves
// qemu directly, skipping the per-engine --describe scan whole-registry
// discovery would spawn.
EngineDescriptor builtin_qemu() {
  EngineDescriptor d;
  d.id = kQemuId;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = 64;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone", "fast-leg"};
  // The hybrid fast-forward leg: load the ELF, drain on the plugin's trigger
  // into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out} are
  // filled by the plan executor (F6); {trigger} is the plugin comma-suffix
  // (empty for marker), folded by leg_trigger_args (F9).
  d.invoke.push_back(
      {"fast-leg",
       {"{bin}", "-object",
        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
        "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
        "enable=on,target=native", "-bios", "{elf}", "-plugin",
        "{plugin},outfile={state_out}{trigger}"}});

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs C-runtime fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv. We pass NO vlen -- the cpu model's own QEMU
  // default applies, so both scalar and vector binaries run out of the box; a
  // user who needs a specific width passes it via the post-`--` -cpu (e.g.
  // -cpu andes-ax46mpv,vlen=512), which still wins. run_passthrough fills
  // {bin}/{elf}.
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax46mpv",
        "-nographic", "-semihosting-config", "enable=on,target=native",
        "-bios", "{elf}"}});

  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / "qemu-system-riscv64").string();
  else
    d.bin_path =
        (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
  return d;
}

namespace {

constexpr int kDescribeTimeoutMs = 5000;

bool is_executable_file(const fs::path& p) {
  std::error_code ec;
  if (!fs::is_regular_file(p, ec)) return false;
  return ::access(p.c_str(), X_OK) == 0;
}

std::string read_file(const fs::path& p) {
  std::ifstream f(p, std::ios::binary);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();

#include "cli.hpp"

namespace andes_sim {
namespace {

// Try to read an option's value at args[i]. Supports both `--flag value`
// (consumes the next token, advancing i) and `--flag=value`.
//   returns  1 = matched, `out` set
//            0 = this token is not `flag`
//           -1 = matched `--flag` but no value follows
int match_opt(const std::vector<std::string>& args, size_t& i,
              const std::string& flag, std::string& out) {
  const std::string& a = args[i];
  if (a == flag) {
    if (i + 1 >= args.size()) return -1;
    out = args[++i];
    return 1;
  }
  const std::string pfx = flag + "=";
  if (a.starts_with(pfx)) {
    out = a.substr(pfx.size());
    return 1;
  }
  return 0;
}

}  // namespace

Cli parse_cli(const std::vector<std::string>& args) {
  Cli c;
  if (args.empty()) return c;  // no subcommand; caller prints usage

  // First token is the subcommand, unless it is a top-level help request.
  if (args[0] == "-h" || args[0] == "--help") {
    c.help = true;
    return c;
  }
  c.subcommand = args[0];

  for (size_t i = 1; i < args.size(); ++i) {
    const std::string& a = args[i];

    if (a == "--") {  // the passthrough boundary: rest is verbatim
      c.has_passthrough = true;
      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
      break;
    }
    if (a == "-h" || a == "--help") {
      c.help = true;
      continue;
    }

    const struct {
      const char* flag;
      std::string* out;
    } opts[] = {{"--mode", &c.model},
                {"--engine", &c.engine},
                {"--trigger", &c.trigger}};
    bool consumed = false;
    for (const auto& o : opts) {
      int r = match_opt(args, i, o.flag, *o.out);
      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
      if (r > 0) { consumed = true; break; }
    }
    if (consumed) continue;

    if (a.size() > 1 && a[0] == '-') {
      c.error = "unknown option: " + a;
      return c;
    }
    c.positional.push_back(a);
  }

  return c;
}

Cli parse_cli(int argc, char** argv) {
  std::vector<std::string> args;
  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
  return parse_cli(args);
}

}  // namespace andes_sim
// andesim command-line parsing.
//
// The grammar is deliberately tiny and stable across all subcommands:
//
//   andesim <cmd> [--mode M] [--engine E] [--trigger T] [positional...]
//                   [-- <verbatim engine args...>]
//
// The single most important rule is the `--` boundary: every token after the
// first `--` is captured verbatim into `passthrough` and is NOT interpreted by
// the framework. That is what lets `fast`/`cycle` forward an engine's whole
// native CLI (e.g. `-gdb tcp::1234 -S`) untouched, so users see one simulator.
#ifndef ANDESIM_CLI_HPP
#define ANDESIM_CLI_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct Cli {
  std::string subcommand;                 // e.g. "run", "list"; "" if none
  std::string model;                      // --mode fast|cycle|hybrid (field stays 'model': the concept, see list models)
  std::string engine;                     // --engine <id>
  std::string trigger;                    // --trigger marker|pc
  std::vector<std::string> positional;    // non-flag framework args
  std::vector<std::string> passthrough;   // verbatim, everything after `--`
  bool help = false;                      // -h / --help (before `--`)
  bool has_passthrough = false;           // a `--` boundary was present
  std::string error;                      // non-empty => parse failed
};

// Parse argv[1..] (program name skipped). The vector overload is the testable
// core; the argv overload adapts it for main().
Cli parse_cli(const std::vector<std::string>& args);
Cli parse_cli(int argc, char** argv);

}  // namespace andes_sim

#endif  // ANDESIM_CLI_HPP

