1	// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / cycle
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <cstdlib>
11	#include <exception>
12	#include <string>
13	#include <string_view>
14	
15	#include "cli.hpp"
16	#include "dev_mode.hpp"
17	#include "repo_root.hpp"
18	
19	namespace andes_sim {
20	int cmd_list(const Cli& cli);
21	}  // namespace andes_sim
22	
23	namespace {
24	
25	using andes_sim::Cli;
26	using andes_sim::is_dev_mode;
27	
28	// Known command names. list has a handler (dispatched in main); the rest are
29	// stable slots for unfinished features, kept here so `find` routes them to
30	// the "not yet implemented" stub rather than "unknown command", while never
31	// appearing in `--help` (print_usage renders only the list block, so the
32	// product never advertises half-built work). Developer build/test tooling
33	// lives in scripts/, not the binary. Display strings (briefs) live in the
34	// help model below.
35	struct Subcommand {
36	  std::string_view name;
37	};
38	
39	constexpr Subcommand kSubcommands[] = {
40	    {"list"},
41	    {"profile"},
42	    {"cluster"},
43	    {"estimate"},
44	};
45	
46	const Subcommand* find(std::string_view name) {
47	  for (const Subcommand& s : kSubcommands)
48	    if (s.name == name) return &s;
49	  return nullptr;
50	}

